def sha(b):return hashlib.sha256(b).hexdigest()
def need(v,m):
 if not v:raise ValueError(m)
def encoded(o):return json.dumps(o,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def identity(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_gid,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def valid_run(run):
 need(isinstance(run,str)and re.fullmatch(r'20[0-9]{6}T[0-9]{6}Z',run),'Unsafe run ID');datetime.datetime.strptime(run,'%Y%m%dT%H%M%SZ');return run

def canonical_parts(raw):
 need(sha(raw)==CANONICAL_SHA,'Canonical migration bytes differ')
 anchor=b'DO $$\nDECLARE\n  invalid_function_count integer;\n  readiness_trigger_count integer;\nBEGIN\n'
 need(raw.count(anchor)==1,'Canonical assertion anchor')
 a=raw.index(anchor);tail=b'\n$$;\n\nCOMMIT;\n';need(raw.count(tail)==1,'Canonical assertion end')
 b=raw.index(tail,a)+len(b'\n$$;');assertion=raw[a:b]
 need(sha(assertion)==ASSERTION_SHA,'Canonical assertion bytes')
 bodies={n.decode():body for n,body in re.findall(rb'CREATE OR REPLACE FUNCTION proof_indexer\.([a-z_]+)\(\).*?AS \$\$(.*?)\$\$;',raw,re.S)}
 need(set(bodies)==set(FUNCTION_HASHES),'Canonical functions')
 for n,(h,size)in FUNCTION_HASHES.items():need(sha(bodies[n])==h and len(bodies[n])==size,'Canonical function bytes')
 return assertion,bodies

