 ident=o['identity'];need(ident['database']=='proof_indexer'and ident['user']=='postgres'and ident['transactionReadOnly']=='on'and ident['searchPath']=='pg_catalog, pg_temp'and int(ident['serverVersion'])//10000==16 and ident['maxPreparedTransactions']=='0','Native SQL identity')
 c=o['closure'];need(set(c)=={'schema','functions','relations','triggers','ownerRole'}and c['schema']=='pow-audit30-readiness-public-closure-v1','Closure schema')
