  expected={'owner':'proof_indexer_readiness_owner','language':'plpgsql','securityDefiner':True,'config':['search_path=pg_catalog, pg_temp'],'kind':'f','argumentCount':0,'returnsSet':False,'returnTypeOid':2279,'volatility':'v','parallel':'u','strict':False,'leakProof':False,'supportOid':0,'sourceSha256':h,'sourceBytes':n,'canonicalSourceEquality':True}
  need(all(f.get(k)==v for k,v in expected.items()),'Function source/identity contract')
