 props=['User=postgres','Group=postgres','NoNewPrivileges=yes','PrivateNetwork=yes','PrivateTmp=yes','PrivateDevices=yes','PrivateIPC=yes','ProtectSystem=strict','ProtectHome=yes','CapabilityBoundingSet=','AmbientCapabilities=','RestrictAddressFamilies=AF_UNIX','RuntimeMaxSec=75s','TimeoutStopSec=5s','KillMode=control-group','MemoryMax=128M','MemorySwapMax=0','CPUQuota=50%','TasksMax=16','UMask=0077','UnsetEnvironment=LD_PRELOAD LD_LIBRARY_PATH PGSERVICE PGSERVICEFILE PGPASSWORD PGPASSFILE PGUSER PGDATABASE PGOPTIONS']
 argv=['/usr/bin/systemd-run','--quiet','--wait','--pipe','--unit='+unit,'--service-type=exec',*['--property='+p for p in props],'/usr/bin/env','-i','PATH=/usr/lib/postgresql/16/bin:/usr/bin:/bin','LC_ALL=C','TZ=UTC','PGHOST=/var/run/postgresql','PGPORT=5432','PGDATABASE=proof_indexer','PGOPTIONS=-c default_transaction_read_only=on -c statement_timeout=60000 -c lock_timeout=3000 -c idle_in_transaction_session_timeout=10000','/usr/lib/postgresql/16/bin/psql','-X','-q','-t','-A','-v','ON_ERROR_STOP=1','-d','proof_indexer']
 sql=build_sql();stdout=job/'public-closure-output.jsonl';stderr=job/'stderr-private.txt';fds=[os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)for p in(stdout,stderr)]
