 after={u:state(u)for u in UNITS};source_after=source_proof(SOURCE_PATH);stopped=state(unit);need(stopped.get('MainPID','0')=='0'and stopped['ActiveState']in('inactive','failed'),'SQL unit still active')
 out={'schema':'pow-audit30-readonly-readiness-closure-v1','approvalSha256':APPROVAL_SHA,'atUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'job':str(job),'canonicalMigrationSha256':CANONICAL_SHA,'canonicalAssertionSha256':ASSERTION_SHA,'closureQuerySha256':CLOSURE_SQL_SHA,'sqlSha256':sha(sql.encode()),'stdoutSha256':sha(b),'stdoutBytes':len(b),'stderrSha256':sha(err),'stderrBytes':len(err),'sqlReturnCode':result.returncode,'sqlStopped':True,'liveServicesUnchanged':before==after,'liveServices':before,'sourceBefore':source_before,'sourceUnchanged':source_before==source_after,'productionDataMutation':False,'privateCatalogExported':False,'ok':False,'canonicalContractAccepted':False,'qualification':'Read-only source-known canonical catalog/ACL/trigger closure, not a body repair or universal data-integrity certificate. No function bodies or private catalog content are exported.'}
 rows=[json.loads(x)for x in b.splitlines()if x.strip()]
