def emit_remote(run):
 valid_run(run);p=pathlib.Path(__file__);raw=p.read_text();marker="\nif __name__=='__main__':"
 need(raw.count(marker)==1,'Local source boundary');return raw.split(marker)[0]+'\nraise SystemExit(remote_main('+repr(run)+'))\n'
def main():
 a=argparse.ArgumentParser();a.add_argument('--emit-remote-code');a.add_argument('--emit-sql',action='store_true');args=a.parse_args()
 if args.emit_remote_code:sys.stdout.write(emit_remote(args.emit_remote_code));return 0
 if args.emit_sql:sys.stdout.write(build_sql());return 0
